/**
 * Placeholder filling for template slides.
 *
 * Template shapes carry plain literal text (`[Work item / ticket / feature
 * name]`), not PowerPoint placeholders, and the authors' shape names are
 * autogenerated (`Google Shape;173;p27`). So binding is by the placeholder's
 * own text, with occurrence order disambiguating repeats — WORK ITEM 1 and
 * WORK ITEM 2 both say `[Work item / ticket / feature name]`, and there is no
 * other stable handle.
 *
 * Every paragraph in these templates holds exactly one run, so a paragraph is
 * replaced by rewriting its single `<a:t>` node. Formatting lives on `<a:rPr>`
 * and is untouched.
 */
import { escapeText } from "./package.js";
const TEXT_NODE = /<a:t>([\s\S]*?)<\/a:t>/g;
/**
 * A `<p:sp>` block. Safe to match non-greedily because these slides are flat:
 * no `<p:grpSp>` nesting and no shape inside a shape (verified on the shipped
 * template). A grouped shape would need real XML traversal.
 */
const SHAPE = /<p:sp>[\s\S]*?<\/p:sp>/g;
const SHAPE_ID = /<p:cNvPr[^>]*\bid="(\d+)"/;
const EMU_PER_INCH = 914400;
/** Every `<p:sp>` on a slide, with geometry in inches and its text. */
export function readShapes(xml) {
    const out = [];
    for (const block of xml.match(SHAPE) ?? []) {
        const id = SHAPE_ID.exec(block)?.[1];
        const off = /<a:off x="(-?\d+)" y="(-?\d+)"\/>/.exec(block);
        const ext = /<a:ext cx="(\d+)" cy="(\d+)"\/>/.exec(block);
        if (id === undefined || !off || !ext)
            continue;
        out.push({
            id,
            x: Number(off[1]) / EMU_PER_INCH,
            y: Number(off[2]) / EMU_PER_INCH,
            w: Number(ext[1]) / EMU_PER_INCH,
            h: Number(ext[2]) / EMU_PER_INCH,
            text: unescapeXml([...block.matchAll(/<a:t>([\s\S]*?)<\/a:t>/g)].map((m) => m[1] ?? "").join("")),
        });
    }
    return out;
}
/**
 * Reposition or resize one shape, in inches.
 *
 * Used to reclaim space a removed block left behind: with the next-week panel
 * gone, the blockers text was still confined to half the slide, which is what
 * forced it to wrap and get truncated.
 */
export function setShapeBox(xml, id, box) {
    const EMU = 914400;
    let done = false;
    return xml.replace(SHAPE, (block) => {
        if (done || SHAPE_ID.exec(block)?.[1] !== id)
            return block;
        done = true;
        let out = block;
        if (box.x !== undefined || box.y !== undefined) {
            out = out.replace(/<a:off x="(-?\d+)" y="(-?\d+)"\/>/, (_m, x, y) => {
                const nx = box.x === undefined ? Number(x) : Math.round(box.x * EMU);
                const ny = box.y === undefined ? Number(y) : Math.round(box.y * EMU);
                return `<a:off x="${nx}" y="${ny}"/>`;
            });
        }
        if (box.w !== undefined || box.h !== undefined) {
            out = out.replace(/<a:ext cx="(\d+)" cy="(\d+)"\/>/, (_m, cx, cy) => {
                const nw = box.w === undefined ? Number(cx) : Math.round(box.w * EMU);
                const nh = box.h === undefined ? Number(cy) : Math.round(box.h * EMU);
                return `<a:ext cx="${nw}" cy="${nh}"/>`;
            });
        }
        return out;
    });
}
/**
 * Set one shape's text, clamped to that shape's own box.
 *
 * The manifest executor writes by shape id, bypassing `fillSlide`'s per-shape
 * budget, so it must apply the same fit rule itself — otherwise a long value in
 * a small slot grows the box (`spAutoFit`) and collides with its neighbour.
 */
export function setShapeTextFitted(xml, id, text) {
    const block = (xml.match(SHAPE) ?? []).find((b) => SHAPE_ID.exec(b)?.[1] === id);
    if (block === undefined)
        return xml;
    const { w, h, pt } = boxOf(block);
    const nodes = block.match(TEXT_NODE)?.length ?? 1;
    return setShapeText(xml, id, clampToBudget(text, charBudget(w, h, pt) / Math.max(1, nodes)));
}
/** Rewrite one shape's text, keeping its first run's formatting. */
export function setShapeText(xml, id, text) {
    let done = false;
    return xml.replace(SHAPE, (block) => {
        if (done || SHAPE_ID.exec(block)?.[1] !== id)
            return block;
        done = true;
        let first = true;
        return block.replace(TEXT_NODE, () => {
            if (first) {
                first = false;
                return `<a:t>${escapeText(text)}</a:t>`;
            }
            return "<a:t></a:t>";
        });
    });
}
/**
 * Copy a set of shapes `copies` times, offsetting each copy down by `dyIn`.
 *
 * The summary "table" is not an `<a:tbl>` — it is six text boxes per row, so
 * adding a row means cloning that row's shapes with fresh ids and a new y.
 * Copies are appended in source order, so a row's background panels stay behind
 * its cells (later shapes paint on top).
 */
export function cloneShapes(xml, ids, copies, dyIn) {
    if (copies <= 0)
        return { xml, created: [] };
    const blocks = new Map();
    let maxId = 0;
    for (const block of xml.match(SHAPE) ?? []) {
        const id = SHAPE_ID.exec(block)?.[1];
        if (id === undefined)
            continue;
        maxId = Math.max(maxId, Number(id));
        blocks.set(id, block);
    }
    const created = [];
    let appended = "";
    for (let c = 1; c <= copies; c++) {
        const rowIds = [];
        for (const id of ids) {
            const source = blocks.get(id);
            if (source === undefined)
                continue;
            const newId = String(++maxId);
            rowIds.push(newId);
            appended += source
                .replace(new RegExp(`(<p:cNvPr[^>]*\\bid=")${id}(")`), `$1${newId}$2`)
                .replace(new RegExp(`(<p:cNvPr[^>]*\\bname="[^"]*?)${id}`), `$1${newId}`)
                .replace(/<a:off x="(-?\d+)" y="(-?\d+)"\/>/, (_m, x, y) => `<a:off x="${x}" y="${String(Number(y) + Math.round(dyIn * c * EMU_PER_INCH))}"/>`);
        }
        created.push(rowIds);
    }
    return { xml: xml.replace("</p:spTree>", `${appended}</p:spTree>`), created };
}
/**
 * Delete whole shapes by id.
 *
 * Used to drop a section the week has no content for. Removing the shape — as
 * opposed to blanking its text — is the difference between "this slide has no
 * second work item" and "this slide has an empty box where one should be".
 *
 * Ids are matched rather than names because shape names carry a slide-specific
 * suffix (`Google Shape;179;p27`), while the id is stable and survives cloning.
 */
export function removeShapesById(xml, ids) {
    const wanted = new Set(ids);
    const removed = [];
    const out = xml.replace(SHAPE, (block) => {
        const id = SHAPE_ID.exec(block)?.[1];
        if (id === undefined || !wanted.has(id))
            return block;
        removed.push(id);
        return "";
    });
    return {
        xml: out,
        removed,
        missing: [...wanted].filter((id) => !removed.includes(id)),
    };
}
/**
 * Template placeholders are written as `[like this]`. Static labels ("REPOS",
 * "WEEK") are plain text and are not reportable — listing them as "unfilled"
 * buries the few placeholders that genuinely need a human.
 */
const PLACEHOLDER = /^\[[\s\S]*\]$/;
const isPlaceholder = (text) => PLACEHOLDER.test(text.trim());
function unescapeXml(s) {
    return s
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, '"')
        .replace(/&apos;/g, "'")
        .replace(/&amp;/g, "&");
}
/**
 * Apply bindings to one slide's XML.
 *
 * Unfilled placeholders are left untouched rather than blanked: a visible
 * `[…#142]` tells the author a field still needs a human, whereas an empty box
 * silently asserts "there were none", which may be false.
 */
/**
 * Character budget for a shape, from its box and font size.
 *
 * Template slots are sized for stubs ("[None]", "[Dependency / decision]"), but
 * bound values are model prose. Without a budget a long sentence overflows, and
 * because these shapes use `spAutoFit` the box then GROWS and collides with the
 * shape beneath it — which reads as stacked text.
 *
 * The 0.52 advance-width ratio is a deliberate overestimate for a proportional
 * face, so the budget errs toward truncating rather than overflowing.
 */
function charBudget(wIn, hIn, sizePt) {
    if (wIn <= 0 || hIn <= 0 || sizePt <= 0)
        return 0;
    const charsPerLine = Math.floor((wIn * 72) / (sizePt * 0.52));
    // Whole lines only: `charsPerLine * 1.26` would admit text that wraps to two
    // lines inside a box that fits one, which is how overflow survives a budget.
    const lines = Math.max(1, Math.floor((hIn * 72) / (sizePt * 1.22)));
    return Math.max(8, charsPerLine * lines);
}
/** Truncate at a word boundary so the result reads as a clipped phrase. */
function clampToBudget(text, budget) {
    if (text.length <= budget)
        return text;
    const cut = text.slice(0, Math.max(1, budget - 1));
    const space = cut.lastIndexOf(" ");
    return `${(space > budget * 0.5 ? cut.slice(0, space) : cut).trimEnd()}\u2026`;
}
/** Geometry of the shape enclosing a block, for the fit check. */
function boxOf(block) {
    const ext = /<a:ext cx="(\d+)" cy="(\d+)"\/>/.exec(block);
    const sz = /\bsz="(\d+)"/.exec(block);
    return {
        w: ext ? Number(ext[1]) / 914400 : 0,
        h: ext ? Number(ext[2]) / 914400 : 0,
        pt: sz ? Number(sz[1]) / 100 : 12,
    };
}
export function fillSlide(xml, bindings) {
    const counts = new Map();
    const filled = [];
    const unfilled = [];
    const seenUnfilled = new Set();
    // Clamp is applied per SHAPE, not per value: the budget depends on the box the
    // text lands in. A long value in a small slot is what produces stacked text,
    // because these shapes use spAutoFit and grow into whatever sits beneath.
    const out = xml.replace(SHAPE, (block) => {
        const { w, h, pt } = boxOf(block);
        const nodes = block.match(TEXT_NODE)?.length ?? 1;
        const perNode = charBudget(w, h, pt) / Math.max(1, nodes);
        return block.replace(TEXT_NODE, (match, inner) => {
            const key = unescapeXml(inner);
            const value = bindings[key];
            if (value === undefined) {
                if (isPlaceholder(key) && !seenUnfilled.has(key)) {
                    seenUnfilled.add(key);
                    unfilled.push(key);
                }
                return match;
            }
            const index = counts.get(key) ?? 0;
            counts.set(key, index + 1);
            const raw = Array.isArray(value) ? value[index] : value;
            if (raw === undefined) {
                if (isPlaceholder(key) && !seenUnfilled.has(key)) {
                    seenUnfilled.add(key);
                    unfilled.push(key);
                }
                return match;
            }
            if (!filled.includes(key))
                filled.push(key);
            return `<a:t>${escapeText(clampToBudget(raw, perNode))}</a:t>`;
        });
    });
    return { xml: out, filled, unfilled };
}
